export type GetHeatmapTileData = {
    body?: never;
    path: {
        /**
         * The renderer and its look, from the renderer descriptor's tile URL template
         */
        rendering: string;
        revision: string;
        z: number;
        x: number;
        y: number;
    };
    query?: {
        /**
         * Inclusive lower bound on the Activity start time
         */
        from?: string;
        /**
         * Exclusive upper bound on the Activity start time
         */
        to?: string;
        /**
         * Sports to include; all sports when absent
         */
        sports?: Array<'RUN' | 'WALK' | 'HIKE' | 'RIDE' | 'SWIM' | 'WORKOUT'>;
    };
    url: '/api/heatmap/tiles/{rendering}/{revision}/{z}/{x}/{y}';
};

